-- Standalone: Kansas (race 4) predictions + feature importances.
-- Safe to re-run; replaces any existing Kansas rows.
begin;
update races set blend_note = '60% intermediate season form / 40% Kansas Chase history' where chase_round = 4;

delete from predictions where race_id = (select id from races where chase_round = 4);
delete from feature_importances where race_id = (select id from races where chase_round = 4);


commit;
